source='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    active = [any(v != bg for v in row) for row in grid]
    bands = []
    r = 0
    while r < h:
        if not active[r]:
            r += 1; continue
        a = r
        while r < h and active[r]: r += 1
        bands.append((a, r))
    xmax = [max(c for rr in range(a,b) for c,v in enumerate(grid[rr]) if v != bg) for a,b in bands]
    # Reuse a more complete, matching band as the stencil for the unfinished band.
    for ti, (ta,tb) in enumerate(bands):
        best = None
        for si, (sa,sb) in enumerate(bands):
            if si == ti or sb-sa != tb-ta or xmax[si] <= xmax[ti]:
                continue
            for shift in range(-w+1, w):
                same = total = 0
                for k in range(tb-ta):
                    for x in range(xmax[ti]+1):
                        sx = x-shift
                        if 0 <= sx < w:
                            total += 1
                            same += grid[ta+k][x] == grid[sa+k][sx]
                if total < max(4, (xmax[ti]+1)*(tb-ta)//2):
                    continue
                score = same/total
                cand = (score, xmax[si], si, shift)
                if best is None or cand > best: best = cand
        if best and best[0] >= 0.88:
            _, _, si, shift = best
            sa,sb = bands[si]
            for k in range(tb-ta):
                for x in range(xmax[ti]+1, w):
                    sx = x-shift
                    if 0 <= sx < w and grid[sa+k][sx] != bg and grid[ta+k][x] == bg:
                        out[ta+k][x] = 1
    # For isolated horizontal bars (and three-row bars), continue the rightmost bar.
    for a,b in bands:
        if b-a == 1:
            xs = [c for c,v in enumerate(grid[a]) if v != bg]
            if xs and xs[-1] < w-1 and all(grid[a][c] == grid[a][0] for c in range(xs[-1]+1)):
                for c in range(xs[-1]+1,w):
                    if out[a][c] == bg: out[a][c] = 1
        elif b-a == 3:
            bandmax = max(c for rr in range(a,b) for c,v in enumerate(grid[rr]) if v != bg)
            rows = [rr for rr in range(a,b) if max(c for c,v in enumerate(grid[rr]) if v != bg) == bandmax]
            for rr in rows:
                xs = [c for c,v in enumerate(grid[rr]) if v != bg]
                if len(xs) >= 2 and xs[-1] < w-1:
                    d = xs[-1]-xs[-2]
                    if d > 1:
                        for c in range(xs[-1]+d,w,d):
                            if out[rr][c] == bg: out[rr][c] = 1
                    elif xs[0] == 0 and all(grid[rr][c] != bg for c in range(xs[-1]+1)):
                        for c in range(xs[-1]+1,w):
                            if out[rr][c] == bg: out[rr][c] = 1
    return out
'''
